test('invoiceTotals: from createInvoice result', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.equal(invoice.ok, true);

  const totals = invoiceTotals(invoice.value);
  const expectedSubtotal = 10 * 9500 + 5 * 8500;
  const expectedDiscount = expectedSubtotal * 0.05;
  assert.deepEqual(totals, { subtotal: expectedSubtotal, discount: expectedDiscount, total: expectedSubtotal - expectedDiscount });
});

